package demo;
import geometry;
import geometry.tools;

geometry.Point p = geometry.Functions.makePoint(1, 2);
geometry.Point q = p;
q.move(3, 4);
print(p.sum());
geometry.Point copied = p.Copy();
copied.move(10, 0);
print(p.sum());
print(copied.sum());
print(geometry.tools.Functions.label());
Nat count = 1000000000000000000000000000000;
