package geometry;
public class Functions{}

public class Point { Int x; Int y; }
static func Functions.secret() Int { return 42; }
public static func Functions.makePoint(Int x, Int y) Point {
    return Point{x:x, y:y};
}
public func Point.sum() Int { return this.x + this.y; }
public func Point.move(Int dx, Int dy) Point {
    this.x = this.x + dx;
    this.y = this.y + dy;
    return this;
}

